.menubar.file add command -label "Copy"  -command {tk_textCopy}
.menubar.file add command -label "Paste" -command {tk_textPaste}

menu .menubar.help
.menubar add cascade -label "Help" -menu .menubar.help
.menubar.help add command -label "About" -command {show_about}

# Create main frame
frame .main_frame -borderwidth 2 -relief groove

# Create notebook (tabbed interface)
